 and (select count(*) from public.spec_templates where tenant_id is null and is_active and key='shifter' and form_contract->'helpers'->>'shifter_control_style'='Cómo se opera la palanca. Es una forma de mando, no una compatibilidad: dos gatillos distintos no son intercambiables por ser gatillos. Un mando integrado con la manilla de freno pertenece a la familia de mando combinado, y esa reasignación se hace con evidencia del producto, no por el título.')=1
